package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
final class AccountSettingsDialog {
 static void show(Context c,boolean password){NativeSheet sheet=new NativeSheet(c,password?"Alterar senha":"Alterar e-mail");EditText old=NativeSheet.input(c,"Senha atual",128),value=NativeSheet.input(c,password?"Nova senha":"Novo e-mail",254),confirm=NativeSheet.input(c,password?"Confirme a nova senha":"Confirme o e-mail",254);if(password){int input=android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD;old.setInputType(input);value.setInputType(input);confirm.setInputType(input);sheet.body.addView(old);}else{value.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);confirm.setInputType(value.getInputType());}sheet.body.addView(value);sheet.body.addView(confirm);if(!password){Button received=new Button(c);received.setText("Já recebi os códigos");sheet.body.addView(received);received.setOnClickListener(v->confirmEmail(c,value.getText().toString()));}TextView state=NativeSheet.text(c,"",13,0xffbea9d7);sheet.body.addView(state);Button save=new Button(c);save.setText("Salvar alteração");AppStyle.button(save,true);sheet.body.addView(save);save.setOnClickListener(v->{String next=value.getText().toString(),check=confirm.getText().toString();if(!next.equals(check)||password&&(next.length()<8||old.getText().toString().isEmpty())||!password&&!android.util.Patterns.EMAIL_ADDRESS.matcher(next).matches()){state.setText(password?"Informe a senha atual e duas senhas novas iguais, com pelo menos 8 caracteres.":"Informe o mesmo e-mail válido nos dois campos.");return;}sheet.busy(true);save.setEnabled(false);new AccountRepository(c).updateAuth(password,next,old.getText().toString(),(rows,error)->{sheet.busy(false);if(error!=null){state.setText(error);save.setEnabled(true);return;}if(!password){sheet.dialog.dismiss();confirmEmail(c,next);return;}old.setText("");value.setText("");confirm.setText("");state.setText(password?"Senha atualizada.":"Pedido enviado. Confirme os links recebidos no endereço atual e no novo, conforme solicitado.");});});sheet.show();}
 static void confirmEmail(Context c,String address){
  NativeSheet sheet=new NativeSheet(c,"Confirmar troca de e-mail");
  sheet.body.addView(NativeSheet.text(c,"Informe o endereço que recebeu o código. Se solicitado, confirme também o código enviado ao outro endereço.",14,0xffbea9d7));
  EditText email=NativeSheet.input(c,"E-mail que recebeu o código",254),code=NativeSheet.input(c,"Código recebido",10);
  email.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);email.setText(address);code.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);
  sheet.body.addView(email);sheet.body.addView(code);TextView state=NativeSheet.text(c,"",13,0xffbea9d7);sheet.body.addView(state);
  Button submit=new Button(c);submit.setText("Confirmar código");AppStyle.button(submit,true);sheet.body.addView(submit);
  submit.setOnClickListener(v->{submit.setEnabled(false);sheet.busy(true);new AccountRepository(c).confirmEmailChange(email.getText().toString(),code.getText().toString(),(rows,error)->{sheet.busy(false);submit.setEnabled(true);if(error!=null){state.setText(error);return;}code.setText("");org.json.JSONObject result=rows.optJSONObject(0);boolean complete=result!=null&&result.optBoolean("complete");state.setText(complete?"E-mail alterado. Use o novo endereço no próximo login.":"Código aceito. Confirme também o código enviado ao outro endereço.");if(complete){submit.setVisibility(android.view.View.GONE);email.setEnabled(false);code.setEnabled(false);}else if(result!=null)email.setText(result.optString("current"));});});sheet.show();
 }

}
